query:
query ($owner: String!, $repo: String!) {
  repository(owner: $owner, name: $repo) {
    baseOfSuggestion: ref(qualifiedName: "refs/heads/sarif-issue27-20260929-a") {
      name prefix
      associatedPullRequests(first: 10) { totalCount nodes { number state headRefName baseRefName } }
    }
    deliveryDeep: refs(refPrefix: "refs/heads/delivery/", query: "00-ci-validation", first: 10) {
      totalCount
      nodes { name prefix associatedPullRequests(first: 10) { totalCount nodes { number headRefName } } }
    }
    deliveryHeads: refs(refPrefix: "refs/heads/", query: "delivery/00-ci-validation", first: 10) {
      totalCount
      nodes { name prefix associatedPullRequests(first: 10) { totalCount nodes { number headRefName } } }
    }
  }
}
